const OFFLINE='levelup-offline-v1';
const pending=new Map();
async function verifiedAsset(url,entry){
 const cache=await caches.open(OFFLINE),key=new URL(url,self.registration.scope).href;
 const saved=await cache.match(key);if(saved&&saved.headers.get('x-lu-sha256')===entry.sha256)return saved;
 if(pending.has(key))return (await pending.get(key)).clone();
 const task=(async()=>{const r=await fetch(new Request(key,{cache:'no-cache'}));if(!r.ok)throw new Error('asset unavailable');const bytes=await r.arrayBuffer();const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');if(sha!==entry.sha256)throw new Error('asset version mismatch');const headers=new Headers(r.headers);headers.set('x-lu-sha256',sha);headers.delete('content-encoding');headers.set('content-length',String(bytes.byteLength));const stored=new Response(bytes,{headers});await cache.put(key,stored.clone());return stored})();pending.set(key,task);try{return (await task).clone()}finally{pending.delete(key)}
}

self.addEventListener('install',event=>{
 // Um arquivo que falhe não impede os outros de ficarem guardados (addAll desistiria de todos).
 // No celular a instalação pode ocorrer durante uma partida. Cada verificação
 // mantém os bytes e cópias da resposta: limita a duas por vez, incluindo ícones.
 event.waitUntil(caches.open(CACHE).then(async cache=>{
  const queue=[...new Set([...CORE,...PRECACHE])];let next=0;
  const worker=async()=>{while(next<queue.length){const url=queue[next++];try{const entry=ASSETS.find(a=>a.url===url);if(entry)await verifiedAsset(url,entry);else await cache.add(new Request(url,{cache:'reload'}))}catch{}}};
  await Promise.all([worker(),worker()]);
 }).catch(()=>{}).then(()=>self.skipWaiting()));
});
// Motor Luau: cada versão tem o próprio endereço runtime/lua-worker.<hash>.js (2,8 MB). Na biblioteca offline
// fica só o desta versão; o anterior sairia do aparelho de qualquer forma (não serve à página nova).
// Página antiga ainda aberta e online continua buscando o dela no site, que guarda os arquivos antigos.
async function pruneOldWorkers(){
 const current=new Set(ASSETS.map(a=>new URL(a.url,self.registration.scope).href)),cache=await caches.open(OFFLINE);
 for(const request of await cache.keys())if(/\/runtime\/lua-worker\.[a-f0-9]{16}\.js$/.test(new URL(request.url).pathname)&&!current.has(request.url.split('?')[0]))await cache.delete(request);
}
self.addEventListener('activate',event=>{
 event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('levelup-')&&key!==CACHE&&!key.startsWith('levelup-offline')).map(key=>caches.delete(key)))).then(()=>ASSETS.length?pruneOldWorkers().catch(()=>{}):undefined).then(()=>self.clients.claim()));
});

async function networkFirst(request,key){
 const cache=await caches.open(CACHE);
 try{const response=await fetch(request,{cache:'no-cache'});if(response.ok)cache.put(key||request,response.clone());return response}
 catch{const cached=await cache.match(key||request,{ignoreSearch:true})||await caches.match(key||request,{ignoreSearch:true});if(cached)return cached;throw new Error('offline')}
}
/** Página (navegação): sempre a versão publicada. O endereço ganha um marcador único para o cache do GitHub Pages
 *  (até 10 min) não entregar a página antiga logo depois de uma publicação. Sem internet: a cópia guardada. */
async function pageFirst(request,key){
 const cache=await caches.open(CACHE);const u=new URL(request.url);u.searchParams.set('lu-v',String(Date.now()));
 try{const response=await fetch(u.href,{cache:'no-store',credentials:'same-origin'});if(response.ok){cache.put(key,response.clone());return response}throw new Error('status '+response.status)}
 catch{const cached=await cache.match(key,{ignoreSearch:true})||await caches.match(key,{ignoreSearch:true});if(cached)return cached;throw new Error('offline')}
}
async function cacheFirst(request){
 const cache=await caches.open(CACHE),cached=await cache.match(request);if(cached)return cached;
 try{const response=await fetch(request);if(response.ok)cache.put(request,response.clone());return response}
 catch(error){const saved=await caches.match(request,{ignoreSearch:true});if(saved)return saved;throw error}
}
async function staleWhileRevalidate(event){
 const cache=await caches.open(CACHE),cached=await cache.match(event.request);
 // Sem internet e sem cópia nesta versão: procura na biblioteca offline (ex.: laboratório Lua baixado).
 const update=fetch(event.request).then(response=>{if(response.ok)cache.put(event.request,response.clone());return response}).catch(async error=>cached||await caches.match(event.request,{ignoreSearch:true})||Promise.reject(error));
 if(cached){event.waitUntil(update);return cached}
 return update;
}

self.addEventListener('fetch',event=>{
 const request=event.request;if(request.method!=='GET')return;
 const url=new URL(request.url);if(url.origin!==self.location.origin)return;
 if(url.searchParams.has('lu-download'))return;
 if(url.pathname.endsWith('/offline-manifest.json')){event.respondWith(networkFirst(request));return}
 if(request.mode==='navigate'){const entry=/\/(login|quiz|jogos)\/?(?:index\.html)?$/.exec(url.pathname);if(entry){const target=new URL(self.registration.scope);target.search=url.search;target.searchParams.set(entry[1],'');event.respondWith(Promise.resolve(Response.redirect(target.href,302)));return}event.respondWith(pageFirst(request,'./').catch(()=>caches.match('./')));return}
 const path=url.pathname;
 const entry=ASSETS.find(a=>new URL(a.url,self.registration.scope).pathname===path);
 if(entry){event.respondWith(verifiedAsset(request.url,entry));return}
 if(/\/sw\.js$/.test(path))return;
 // Manifesto e ícones vão direto ao servidor, sem passar pelo service worker: é o que o iPhone e o Android leem ao instalar.
 if(/\/manifest\.webmanifest$/.test(path)||/\/icons\//.test(path)||/apple-touch-icon/.test(path))return;
 if(/\/index-[\w-]+\.(js|css)$/.test(path)){event.respondWith(cacheFirst(request));return}
 if(/\.(png|webp|jpg|jpeg|gif|svg|js|css|woff2?)$/.test(path)){event.respondWith(staleWhileRevalidate(event));return}
 // Laboratório 3D: personagem (.glb) e peças (.json) ficam guardados depois do primeiro uso (e na biblioteca offline).
 if(/\/studio\/[\w.-]+\.(glb|json)$/.test(path)){event.respondWith(staleWhileRevalidate(event));return}
});

/* Notificações: prontas para receber envios do servidor (push) e abrir a plataforma ao tocar. */
self.addEventListener('push',event=>{
 let data={};try{data=event.data?event.data.json():{}}catch{data={body:event.data&&event.data.text()}}
 const options={body:data.body||'Há novidades na sua plataforma.',icon:'./icons/icon-192-v2.png',badge:'./icons/icon-192-v2.png',tag:data.tag||'levelup',renotify:!!data.tag,timestamp:Date.now(),data:{url:data.url||'./'}};
 // Imagem grande da novidade (Android/Chrome). O ícone continua sendo a logo oficial; o iPhone ignora "image".
 if(typeof data.image==='string'&&/^https:\/\//.test(data.image))options.image=data.image;
 event.waitUntil(self.registration.showNotification(data.title||'Level Up Academy',options));
});
self.addEventListener('notificationclick',event=>{
 event.notification.close();
 const target=new URL((event.notification.data&&event.notification.data.url)||'./',self.registration.scope).href;
 event.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(async list=>{
  const client=list.find(c=>c.url.startsWith(self.registration.scope));
  if(!client)return self.clients.openWindow(target);
  // App já aberto: só foco + mensagem. Nunca force navegação: a página pode
  // estar ocupada no Studio/jogo e não responder dentro do prazo.
  try{await client.focus()}catch{}
  await new Promise(resolve=>{const channel=new MessageChannel();const finish=ok=>{clearTimeout(timer);channel.port1.close();resolve(ok)};const timer=setTimeout(()=>finish(false),1500);channel.port1.onmessage=()=>finish(true);try{client.postMessage({type:'levelup-open',url:target},[channel.port2])}catch{finish(false)}});
  // Mesmo openWindow pode reutilizar um app instalado. Com cliente existente,
  // não o chame como fallback; preservar a partida tem prioridade.
  return client;
 }));
});
